import{_ as e,o as d,c as a,a3 as r}from"./chunks/framework.DeRSg1wr.js";const _=JSON.parse('{"title":"项目特性","description":"TLog 2.0 的日志、框架、异步和配置能力，以及已经验证的范围。","frontmatter":{"title":"项目特性","date":"2022-09-12T13:25:20.000Z","permalink":"/pages/fff1a0/","description":"TLog 2.0 的日志、框架、异步和配置能力，以及已经验证的范围。"},"headers":[],"relativePath":"pages/fff1a0/index.md","filePath":"10.文档/020.项目特性.md"}'),o={name:"pages/fff1a0/index.md"};function i(n,t,c,p,l,s){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="项目特性" tabindex="-1">项目特性 <a class="header-anchor" href="#项目特性" aria-label="Permalink to &quot;项目特性&quot;">​</a></h1><p>TLog 2.0 保留日志标签追踪的使用方式，更新了现代 Spring、日志和异步框架的适配。</p><table tabindex="0"><thead><tr><th>能力</th><th>支持内容</th></tr></thead><tbody><tr><td>日志关联</td><td>traceId、层级 spanId、上下游信息和可配置标签模板</td></tr><tr><td>日志输出</td><td>logback、Log4j2，以及旧 Log4j 适配器；通过配置文件或 MDC 输出</td></tr><tr><td>Spring Boot</td><td>同一套 starter 适配 Boot 2、3、4，自动选择 javax/jakarta Servlet Filter</td></tr><tr><td>HTTP / RPC</td><td>Servlet、WebFlux、Feign、Dubbo/Dubbox，以及对应 HTTP 客户端和网关适配</td></tr><tr><td>自动 HTTP 埋点</td><td>装饰容器中的 RestTemplate、WebClient.Builder、RestClient.Builder；RestClient 要求 Spring 6.1+</td></tr><tr><td>异步</td><td>Spring 执行器自动装饰；<code>TLogExecutors.wrap</code> 覆盖外部 Executor、ExecutorService 和 ScheduledExecutorService</td></tr><tr><td>响应式链路</td><td>Reactor Context 隔离请求，在订阅和信号回调期间恢复 TLog 上下文</td></tr><tr><td>业务标签</td><td><code>@TLogAspect</code> 支持参数表达式、固定文本、连接符和自定义转换器</td></tr><tr><td>消息中间件</td><td>Kafka、RabbitMQ 经消息 header 透传：Spring Kafka / Spring AMQP 自动装配，原生客户端一行接入；其它 MQ 使用消息体包装</td></tr><tr><td>任务</td><td>Spring Scheduled、JDK Timer、Quartz、XXL-JOB 适配</td></tr><tr><td>扩展与开关</td><td>自定义 ID 生成器 Bean、分功能开关、响应头开关和 IDE 配置提示</td></tr><tr><td>W3C 入站</td><td>没有 TLog traceId 时，尝试复用合法 <code>traceparent</code> 的 trace-id</td></tr></tbody></table><p>框架支持不等于任意依赖版本都已逐一测试。TLog 自身为 Java 8 字节码，应用运行 JDK 仍由所选 Spring Boot 和其它框架决定。完整测试矩阵和未覆盖的场景见<a href="/guide/compatibility/">兼容性与验收</a>。</p><p>新版本不再提供 javaagent、<code>AspectLogEnhance.enhance()</code> 或固定“0.01% 损耗”的承诺。线程池、响应式和日志异步队列的传播边界分别见<a href="/pages/a69e1d/">线程池</a>、<a href="/guide/webflux/">WebFlux</a>和<a href="/pages/5223de/">日志适配</a>。</p>',5)])])}const f=e(o,[["render",i]]);export{_ as __pageData,f as default};
